const test = require('node:test');
const assert = require('node:assert');
const { compare } = require('./semver.js');

test('equal versions', () => {
  assert.strictEqual(compare('1.2.3', '1.2.3'), 0);
});

test('smaller minor', () => {
  assert.strictEqual(compare('1.2.3', '1.3.0'), -1);
});

test('bigger minor', () => {
  assert.strictEqual(compare('1.3.0', '1.2.9'), 1);
});

test('patch difference', () => {
  assert.strictEqual(compare('1.2.4', '1.2.3'), 1);
  assert.strictEqual(compare('1.2.3', '1.2.4'), -1);
});

