const test = require('node:test');
const assert = require('node:assert');
const { compare } = require('./semver.js');

test('returns a number', () => {
  assert.strictEqual(typeof compare('1.2.3', '1.2.4'), 'number');
});

test('equal is falsy', () => {
  assert.strictEqual(compare('1.0.0', '1.0.0'), 0);
});

test('in range', () => {
  assert.ok(Math.abs(compare('1.0.0', '2.0.0')) <= 1);
});

test('another', () => {
  assert.ok(compare('2.0.0', '1.0.0') !== null);
});
